#!/usr/bin/env node

/**
 * Wasm Golden Test Runner
 *
 * Builds the gh-aw wasm module, loads it in Node.js, compiles workflow fixtures,
 * and compares the output against golden files generated by the Go test suite.
 *
 * Usage:
 *   node scripts/test-wasm-golden.mjs [--update]
 *
 * The --update flag regenerates golden files from wasm output.
 *
 * Prerequisites:
 *   - Go 1.23+ installed
 *   - Run `make build-wasm` first, or this script will build it
 */

import { readFileSync, readdirSync, writeFileSync, existsSync, mkdirSync } from "fs";
import { join, resolve } from "path";
import { execSync } from "child_process";
import { createRequire } from "module";

const ROOT = resolve(import.meta.dirname, "..");
const FIXTURES_DIR = join(ROOT, "pkg/workflow/testdata/wasm_golden/fixtures");
const GOLDEN_DIR = join(ROOT, "pkg/workflow/testdata/wasm_golden");
const WASM_FILE = join(ROOT, "gh-aw.wasm");
const VERSION_CONSTANTS_FILE = join(ROOT, "pkg/constants/version_constants.go");
const UPDATE_MODE = process.argv.includes("--update");

// Fixtures with known wasm-vs-native divergence due to filesystem limitations.
// The wasm environment cannot fully replicate the native compiler's behavior for
// workflow_run triggers (missing fork validation, zizmor annotations) and
// pre_activation job generation. These are tracked for future resolution.
const KNOWN_WASM_DIVERGENCE = new Set([
  "ci-doctor", // workflow_run trigger: missing zizmor annotation + fork validation
  "copilot-cli-deep-research", // pre_activation job generated differently in wasm
  "dev-hawk", // workflow_run trigger: missing zizmor annotation + fork validation
]);

function escapeRegex(text) {
  return text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function loadDefaultRuntimeVersions() {
  const source = readFileSync(VERSION_CONSTANTS_FILE, "utf8");
  const getVersion = name => {
    const match = source.match(new RegExp(`^const\\s+${name}\\s+Version\\s+=\\s+"([^"]+)"`, "m"));
    if (!match) {
      throw new Error(`Could not find ${name} in ${VERSION_CONSTANTS_FILE}`);
    }
    return match[1];
  };

  const awfVersion = getVersion("DefaultFirewallVersion");
  const copilotChecksumsSHA256 = source.match(/^const DefaultCopilotChecksumsSHA256 = "([0-9a-f]{64})"$/m)?.[1];
  if (!copilotChecksumsSHA256) {
    throw new Error(`Could not find DefaultCopilotChecksumsSHA256 in ${VERSION_CONSTANTS_FILE}`);
  }
  return {
    awfVersion,
    awfImageTag: awfVersion.replace(/^v/, ""),
    mcpgVersion: getVersion("DefaultMCPGatewayVersion"),
    ghMcpVersion: getVersion("DefaultGitHubMCPServerVersion"),
    codexVersion: getVersion("DefaultCodexVersion"),
    piVersion: getVersion("DefaultPiVersion"),
    copilotVersion: getVersion("DefaultCopilotVersion"),
    copilotChecksumsSHA256,
  };
}

const DEFAULT_RUNTIME_VERSIONS = loadDefaultRuntimeVersions();

// ── Build wasm if needed ─────────────────────────────────────────────
function ensureWasmBuilt() {
  if (!existsSync(WASM_FILE)) {
    console.log("Building wasm module...");
    execSync("make build-wasm", { cwd: ROOT, stdio: "inherit" });
  }
  console.log(`Using wasm module: ${WASM_FILE}`);
}

// ── Load Go wasm_exec.js runtime ─────────────────────────────────────
function loadWasmExecJs() {
  const goRoot = execSync("go env GOROOT", { encoding: "utf8" }).trim();
  // Go 1.24+ moved wasm_exec.js from misc/wasm/ to lib/wasm/
  let wasmExecPath = join(goRoot, "lib/wasm/wasm_exec.js");
  if (!existsSync(wasmExecPath)) {
    wasmExecPath = join(goRoot, "misc/wasm/wasm_exec.js");
  }
  if (!existsSync(wasmExecPath)) {
    throw new Error(`wasm_exec.js not found in ${goRoot}/lib/wasm/ or ${goRoot}/misc/wasm/`);
  }
  // Supply Node's filesystem so wasm_exec.js does not fall back to ENOSYS stubs.
  globalThis.require = createRequire(import.meta.url);
  globalThis.fs = globalThis.require("fs");
  // Load the wasm_exec.js script (it defines globalThis.Go)
  const script = readFileSync(wasmExecPath, "utf8");
  // Use indirect eval to run in global scope
  const fn = new Function(script);
  fn();
}

// ── Instantiate wasm module ──────────────────────────────────────────
async function instantiateWasm() {
  const go = new globalThis.Go();
  const wasmBytes = readFileSync(WASM_FILE);
  const result = await WebAssembly.instantiate(wasmBytes, go.importObject);
  // Start the Go runtime (it blocks, runs in background)
  go.run(result.instance);
  // Wait a moment for the Go runtime to register the global function
  await new Promise(r => setTimeout(r, 200));

  if (typeof globalThis.compileWorkflow !== "function") {
    throw new Error("compileWorkflow function not registered by wasm module. " + "Ensure cmd/gh-aw-wasm/main.go sets js.Global().Set('compileWorkflow', ...)");
  }
  console.log("Wasm module loaded, compileWorkflow function available");
  return globalThis.compileWorkflow;
}

// ── Load all shared components as virtual files ─────────────────────
// The wasm binary needs access to shared components for both import
// resolution and security scanning (runtime-import validation).
let _sharedFilesCache = null;
function loadAllSharedFiles() {
  if (_sharedFilesCache) return _sharedFilesCache;
  const files = {};
  const sharedDir = join(FIXTURES_DIR, "shared");
  if (!existsSync(sharedDir)) return null;

  for (const f of readdirSync(sharedDir)) {
    if (f.endsWith(".md")) {
      files[`shared/${f}`] = readFileSync(join(sharedDir, f), "utf8");
    }
  }
  const mcpDir = join(sharedDir, "mcp");
  if (existsSync(mcpDir)) {
    for (const f of readdirSync(mcpDir)) {
      if (f.endsWith(".md")) {
        files[`shared/mcp/${f}`] = readFileSync(join(mcpDir, f), "utf8");
      }
    }
  }
  _sharedFilesCache = Object.keys(files).length > 0 ? files : null;
  return _sharedFilesCache;
}

// ── Load fixtures ────────────────────────────────────────────────────
function loadFixtures() {
  const sharedFiles = loadAllSharedFiles();
  const files = readdirSync(FIXTURES_DIR).filter(f => f.endsWith(".md"));
  return files.map(f => ({
    name: f.replace(/\.md$/, ""),
    filename: f,
    content: readFileSync(join(FIXTURES_DIR, f), "utf8"),
    virtualFiles: sharedFiles,
  }));
}

// ── Normalize heredoc delimiters ─────────────────────────────────────
// Replaces randomized heredoc delimiter tokens (e.g. GH_AW_PROMPT_4e0413dfda20da69_EOF)
// with a stable placeholder so that wasm output and golden files compare equal even
// though each compilation embeds different (or seeded) hex tokens.
// Mirrors normalizeHeredocDelimiters() in pkg/workflow/compiler.go.
function normalizeHeredocDelimiters(content) {
  return content.replace(/GH_AW_([A-Z0-9_]+)_[0-9a-f]{16}_EOF/g, "GH_AW_$1_NORM_EOF");
}

// ── Normalize container pin digests ──────────────────────────────────
// Strips @sha256:<64 hex chars> digest suffixes from Docker image references
// so that compiled output compares equal regardless of whether the action cache
// was loaded (native compilation has it, wasm does not).
// Mirrors normalizeContainerPins() in pkg/workflow/compiler.go.
function normalizeContainerPins(content) {
  return content.replace(/@sha256:[0-9a-f]{64}/g, "");
}

// ── Normalize AWF --image-tag digest suffixes ─────────────────────────
// Strips ",name=sha256:<64 hex chars>" fragments appended to --image-tag values
// so output compares equal when runtime image digests are present in one path but not another.
// Mirrors normalizeOutput() in pkg/workflow/wasm_golden_test.go.
function normalizeAWFImageTagDigests(content) {
  return content.replace(/,[a-z-]+=sha256:[0-9a-f]{64}/g, "");
}

// ── Normalize GH_AW_PROJECT_UTC env line ───────────────────────────────
// Keep wasm-vs-native comparison stable when GH_AW_PROJECT_UTC is emitted
// by one compiler path but not the other.
// Mirrors normalizeOutput() in pkg/workflow/wasm_golden_test.go.
function normalizeProjectUTC(content) {
  return content.replace(/^\s*GH_AW_PROJECT_UTC:.*(?:\r?\n|$)/gm, "");
}

// ── Normalize copilot model fallback ───────────────────────────────────
// Keep golden fixtures stable across copilot default model fallback updates.
// Mirrors normalizeOutput() in pkg/workflow/wasm_golden_test.go.
function normalizeCopilotDefaultModel(content) {
  return content
    .replace(/\|\| 'claude-sonnet-[\d.]+'/g, "|| 'default'")
    .replace(/\|\| 'auto'/g, "|| 'default'")
    .replace(/\|\| 'gpt-[\d.][\w.-]*'/g, "|| 'default'");
}

// ── Normalize AWF config payload ─────────────────────────────────────────
// Keep golden fixtures stable across AWF config payload changes (model aliases,
// domain allowlists, container image tags). The entire JSON body is replaced with
// a stable placeholder so that model/domain additions don't break golden comparisons.
// Mirrors testAWFConfigPayloadRE / normalizeOutput() in pkg/workflow/wasm_golden_test.go.
function normalizeAWFConfigPayload(content) {
  return content.replace(/(printf '%s\\n' ")(\{.*\})(" > "\$\{RUNNER_TEMP\}\/gh-aw\/awf-config\.json")/g, "$1AWF_CONFIG_PAYLOAD$3");
}

// ── Normalize actions/checkout pin ──────────────────────────────────────
// Keep golden fixtures stable across actions/checkout pin version bumps.
// Mirrors testCheckoutPinRE / normalizeOutput() in pkg/workflow/wasm_golden_test.go.
function normalizeCheckoutPin(content) {
  return content.replace(/actions\/checkout@[0-9a-f]{40}\s+#\s+v\d+\.\d+\.\d+/g, "actions/checkout@9c091bb21b7c1c1d1991bb908d89e4e9dddfe3e0 # v7.0.0");
}

// ── Normalize default runtime versions ───────────────────────────────────
// Keep tracked wasm snapshots stable across default AWF/MCPG version bumps
// without masking explicitly pinned non-default versions in fixtures.
function normalizeDefaultRuntimeVersions(content) {
  const { awfVersion, awfImageTag, mcpgVersion, ghMcpVersion, codexVersion, piVersion, copilotVersion, copilotChecksumsSHA256 } = DEFAULT_RUNTIME_VERSIONS;
  return content
    .replace(new RegExp(`GH_AW_INFO_AWF_VERSION: "${escapeRegex(awfVersion)}"`, "g"), 'GH_AW_INFO_AWF_VERSION: "vAWF_VERSION"')
    .replace(new RegExp(`GH_AW_INFO_AWMG_VERSION: "${escapeRegex(mcpgVersion)}"`, "g"), 'GH_AW_INFO_AWMG_VERSION: "vMCPG_VERSION"')
    .replace(new RegExp(`(install_awf_binary\\.sh"\\s+)${escapeRegex(awfVersion)}\\b`, "g"), "$1vAWF_VERSION")
    .replace(new RegExp(`(ghcr\\.io/github/gh-aw-firewall/(?:agent|api-proxy|cli-proxy|squid):)${escapeRegex(awfImageTag)}\\b`, "g"), "$1AWF_VERSION")
    .replace(new RegExp(`(releases/download/)${escapeRegex(awfVersion)}(/awf-config\\.schema\\.json)`, "g"), "$1vAWF_VERSION$2")
    .replace(new RegExp(`("imageTag"\\s*:\\s*")(?:v)?${escapeRegex(awfImageTag)}"`, "g"), '$1AWF_VERSION"')
    .replace(new RegExp(`(ghcr\\.io/github/gh-aw-mcpg:)${escapeRegex(mcpgVersion)}\\b`, "g"), "$1MCPG_VERSION")
    .replace(new RegExp(`(ghcr\\.io/github/github-mcp-server:)${escapeRegex(ghMcpVersion)}\\b`, "g"), "$1GH_MCP_VERSION")
    .replace(new RegExp(`GH_AW_INFO_VERSION: "${escapeRegex(codexVersion)}"`, "g"), 'GH_AW_INFO_VERSION: "CODEX_VERSION"')
    .replace(new RegExp(`GH_AW_INFO_AGENT_VERSION: "${escapeRegex(codexVersion)}"`, "g"), 'GH_AW_INFO_AGENT_VERSION: "CODEX_VERSION"')
    .replace(new RegExp(`(@openai/codex@)${escapeRegex(codexVersion)}\\b`, "g"), "$1CODEX_VERSION")
    .replace(new RegExp(`GH_AW_INFO_VERSION: "${escapeRegex(piVersion)}"`, "g"), 'GH_AW_INFO_VERSION: "PI_VERSION"')
    .replace(new RegExp(`GH_AW_INFO_AGENT_VERSION: "${escapeRegex(piVersion)}"`, "g"), 'GH_AW_INFO_AGENT_VERSION: "PI_VERSION"')
    .replace(new RegExp(`(@earendil-works/pi-coding-agent@)${escapeRegex(piVersion)}\\b`, "g"), "$1PI_VERSION")
    .replace(new RegExp(`GH_AW_INFO_VERSION: "${escapeRegex(copilotVersion)}"`, "g"), 'GH_AW_INFO_VERSION: "COPILOT_VERSION"')
    .replace(new RegExp(`GH_AW_INFO_AGENT_VERSION: "${escapeRegex(copilotVersion)}"`, "g"), 'GH_AW_INFO_AGENT_VERSION: "COPILOT_VERSION"')
    .replace(new RegExp(`(install_copilot_cli\\.sh"\\s+)v?${escapeRegex(copilotVersion)}(\\s+(?:--rootless\\s+)?--checksums-sha256\\s+)${escapeRegex(copilotChecksumsSHA256)}\\b`, "g"), "$1COPILOT_VERSION$2COPILOT_CHECKSUMS_SHA256");
}

// ── Normalize output ──────────────────────────────────────────────────
// Applies all normalizations needed for stable golden comparison.
// Combines heredoc delimiter and container pin normalizations so that
// new normalization steps only need to be added in one place.
// Mirrors normalizeOutput() in pkg/workflow/wasm_golden_test.go.
function normalize(content) {
  return normalizeAWFConfigPayload(normalizeCheckoutPin(normalizeDefaultRuntimeVersions(normalizeCopilotDefaultModel(normalizeProjectUTC(normalizeAWFImageTagDigests(normalizeContainerPins(normalizeHeredocDelimiters(content))))))));
}

// ── Load golden file ─────────────────────────────────────────────────
function loadGoldenFile(testName) {
  // Golden files follow the charmbracelet/x/exp/golden convention:
  // pkg/workflow/testdata/TestWasmGolden_CompileFixtures/<name>.golden
  const goldenPath = join(ROOT, "pkg/workflow/testdata/TestWasmGolden_CompileFixtures", testName + ".golden");
  if (!existsSync(goldenPath)) {
    return null;
  }
  return readFileSync(goldenPath, "utf8");
}

// ── Save wasm golden file ────────────────────────────────────────────
function saveWasmGoldenFile(testName, content) {
  const dir = join(GOLDEN_DIR, "WasmBinary");
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true });
  }
  const goldenPath = join(dir, testName + ".golden");
  writeFileSync(goldenPath, normalize(content));
}

// ── Main test runner ─────────────────────────────────────────────────
async function main() {
  ensureWasmBuilt();
  loadWasmExecJs();
  // Resolve configuration and runtime imports from the same directory as the Go tests.
  process.chdir(FIXTURES_DIR);
  const compileWorkflow = await instantiateWasm();
  const fixtures = loadFixtures();

  console.log(`\nRunning wasm golden tests on ${fixtures.length} fixtures...\n`);

  let passed = 0;
  let failed = 0;
  let skipped = 0;
  const failures = [];

  for (const fixture of fixtures) {
    process.stdout.write(`  ${fixture.name} ... `);

    // Skip fixtures with known wasm-vs-native divergence
    if (!UPDATE_MODE && KNOWN_WASM_DIVERGENCE.has(fixture.name)) {
      console.log("SKIP (known wasm divergence)");
      skipped++;
      continue;
    }

    // Load the golden file once (null if it doesn't exist)
    const goldenYaml = loadGoldenFile(fixture.name);

    // Skip fixtures that have no golden file (Go test also skipped them)
    // unless we're in update mode
    if (!UPDATE_MODE && goldenYaml === null) {
      console.log("SKIP (no golden file)");
      skipped++;
      continue;
    }

    try {
      const result = await compileWorkflow(fixture.content, fixture.virtualFiles, fixture.filename);

      if (result.error) {
        console.log("FAIL (compilation error)");
        failures.push({
          name: fixture.name,
          error: `Wasm compilation error: ${result.error}`,
        });
        failed++;
        continue;
      }

      const wasmYaml = result.yaml;

      if (UPDATE_MODE) {
        saveWasmGoldenFile(fixture.name, wasmYaml);
        console.log("UPDATED");
        passed++;
        continue;
      }

      const normalizedWasm = normalize(wasmYaml);
      const normalizedGolden = normalize(goldenYaml);

      if (normalizedWasm === normalizedGolden) {
        console.log("PASS");
        passed++;
      } else {
        console.log("FAIL (output differs from golden)");

        // Find first difference
        const wasmLines = normalizedWasm.split("\n");
        const goldenLines = normalizedGolden.split("\n");
        for (let i = 0; i < Math.min(wasmLines.length, goldenLines.length); i++) {
          if (wasmLines[i] !== goldenLines[i]) {
            failures.push({
              name: fixture.name,
              error: `First diff at line ${i + 1}:\n  wasm:   ${JSON.stringify(wasmLines[i])}\n  golden: ${JSON.stringify(goldenLines[i])}`,
            });
            break;
          }
        }
        if (wasmLines.length !== goldenLines.length) {
          failures.push({
            name: fixture.name,
            error: (failures.length > 0 ? failures[failures.length - 1].error + "\n" : "") + `Line count: wasm=${wasmLines.length}, golden=${goldenLines.length}`,
          });
        }
        failed++;
      }
    } catch (err) {
      // Match Go test behavior: skip fixtures that cannot compile in the
      // wasm/js environment. Some fixtures compile fine with disk access
      // (Go test) but fail in wasm due to missing filesystem support.
      const msg = err.message || String(err);
      const isWasmLimitation =
        msg.includes("not implemented on js") ||
        msg.includes("import file not found") ||
        msg.includes("must be within .github folder") ||
        msg.includes("fuzzy cron expression") ||
        msg.includes("Configuration error") ||
        msg.includes("Validation failed") ||
        msg.includes("file not found in virtual filesystem");
      if (isWasmLimitation) {
        console.log(`SKIP (cannot compile in wasm: ${msg})`);
        skipped++;
      } else {
        console.log("ERROR");
        failures.push({
          name: fixture.name,
          error: `Exception: ${msg}`,
        });
        failed++;
      }
    }
  }

  // Summary
  console.log(`\n${"=".repeat(60)}`);
  console.log(`Results: ${passed} passed, ${failed} failed, ${skipped} skipped (${fixtures.length} total)`);

  if (failures.length > 0) {
    console.log(`\nFailures:`);
    for (const f of failures) {
      console.log(`\n  ${f.name}:`);
      console.log(`    ${f.error.replace(/\n/g, "\n    ")}`);
    }
  }

  if (UPDATE_MODE) {
    console.log(`\nWasm golden files updated in ${GOLDEN_DIR}/WasmBinary/`);
  }

  console.log();
  process.exit(failed > 0 ? 1 : 0);
}

main().catch(err => {
  console.error("Fatal error:", err);
  process.exit(2);
});
